const data = $input.first().json;
const params = $('パラメータ構築1').first().json;
const isHistorical = params.isHistorical;

let result;

if (!isHistorical) {
  const day = data.forecast?.forecastday?.[0]?.day;
  const condition = day?.condition;
  if (!day) return [{ json: { error: 'No forecast data' } }];

  const tmax = Math.round(day.maxtemp_c);
  const tmin = Math.round(day.mintemp_c);
  const rainChance = day.daily_chance_of_rain || 0;
  const condText = condition?.text || '';
  const condCode = condition?.code || 1000;

  let cond = 'mild';
  if (tmax >= 30) cond = 'hot';
  else if ([1066,1114,1117,1210,1213,1216,1219,1222,1225,1255,1258].includes(condCode)) cond = 'snow';
  else if (tmax <= 5) cond = tmin <= 0 ? 'snow' : 'cold';
  else if (rainChance >= 60) cond = 'rain';

  result = { isHistorical: false, tmax, tmin, condText, rainChance, cond };
} else {
  const daily = data.daily;
  if (!daily) return [{ json: { error: 'No historical data' } }];

  const allMax = daily.temperature_2m_max.filter(v => v != null);
  const allMin = daily.temperature_2m_min.filter(v => v != null);
  const precip = daily.precipitation_sum.filter(v => v != null);

  const avgMax = allMax.length ? Math.round(allMax.reduce((a,b)=>a+b,0)/allMax.length) : 0;
  const avgMin = allMin.length ? Math.round(allMin.reduce((a,b)=>a+b,0)/allMin.length) : 0;
  const rainPct = precip.length ? Math.round(precip.filter(v=>v>1).length/precip.length*100) : 0;

  let cond = 'mild';
  if (avgMax >= 30) cond = 'hot';
  else if (avgMax <= 5 && avgMin <= 0) cond = 'snow';
  else if (avgMax <= 8) cond = 'cold';
  else if (rainPct >= 50) cond = 'rain';

  result = { isHistorical: true, tmax: avgMax, tmin: avgMin, rainPct, cond };
}

return [{ json: result }];

const query = $input.first().json.query;
const lat = query.lat || '35.68';
const lon = query.lon || '139.76';
const date = query.start_date || '';
const today = new Date();
today.setHours(0,0,0,0);
const dep = new Date(date);
const diffDays = Math.round((dep - today) / (1000 * 60 * 60 * 24));

let apiUrl;
let isHistorical = false;

if (diffDays <= 14) {
  // APIキーはHTTPリクエストノード側のCredential(Query Auth)で自動付与されるため、ここには含めない
  apiUrl = `https://api.weatherapi.com/v1/forecast.json?q=${lat},${lon}&dt=${date}&lang=ja`;
} else {
  isHistorical = true;
  const d = new Date(date);
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  const prevYear = new Date().getFullYear() - 1;
  apiUrl = `https://archive-api.open-meteo.com/v1/archive?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=Asia%2FTokyo&start_date=${prevYear}-${month}-01&end_date=${prevYear}-${month}-${lastDay}`;
}

return [{ json: { apiUrl, isHistorical } }];
